sdkTypes.SDKResponse:
export type SDKResponse<TData, TError = unknown> =
  | {
      data: TData;
      error?: never;
      response: Response;
    }
  | {
      data?: never;
      error: TError;
      response: Response;
    };

sdkTypes.SDKRequestInit:
export interface SDKRequestInit<TBody = unknown> {
  body?: TBody;
  headers?: SDKHeaders;
  params?: {
    query?: Record<string, unknown>;
    header?: Record<string, unknown>;
    path?: Record<string, unknown>;
    cookie?: Record<string, unknown>;
  };
  parseAs?: 'json' | 'text' | 'blob' | 'arrayBuffer' | 'stream';
  [key: string]: unknown;
}

sdkTypes.ConversationModelId:
export interface ConversationModelId {
  /** Application/model unique identifier. */
  id: string;
  [key: string]: unknown;
}

sdkTypes.ConversationMessageSettings:
export interface ConversationMessageSettings {
  prompt: string;
  temperature: number;
  [key: string]: unknown;
}

sdkTypes.ConversationMessage:
export interface ConversationMessage {
  role: string;
  content: string;
  model?: ConversationModelId;
  settings?: ConversationMessageSettings;
  [key: string]: unknown;
}

sdkTypes.Conversation:
export interface Conversation {
  /** Conversation unique identifier. */
  id: string;
  /** Path to the folder where conversation is located according to the user's root. */
  folderId: string;
  /** Display name. */
  name: string;
  /** System prompt. */
  prompt: string;
  temperature: number;
  lastActivityDate?: number;
  model: ConversationModelId;
  messages: ConversationMessage[];
  customViewState?: Record<string, unknown>;
  [key: string]: unknown;
}

sdkTypes.ConversationResource:
export interface ConversationResource {
  name?: string;
  author?: string;
  parentPath?: string;
  bucket?: string;
  url?: string;
  nodeType?: string;
  resourceType?: 'CONVERSATION' | string;
  etag?: string;
  createdAt?: number;
  updatedAt?: number;
  permissions?: string[];
  [key: string]: unknown;
}

sdkTypes.ModelListData:
export interface ModelListData {
  /** An array of models. */
  data?: ModelData[];
  [key: string]: unknown;
}

sdkOptions:
export interface SDKOptions {
  baseUrl: string;
  apiKey?: string;
  token?: string;
  headers?: Record<string, string>;
  fetch?: typeof fetch;
}
